   256  // One job of row loopfiltering.
   257  void av1_thread_loop_filter_rows(
   258      const YV12_BUFFER_CONFIG *const frame_buffer, AV1_COMMON *const cm,
   259      struct macroblockd_plane *planes, MACROBLOCKD *xd, int mi_row, int plane,
   260      int dir, int lpf_opt_level, AV1LfSync *const lf_sync,
   261      struct aom_internal_error_info *error_info,
   262      AV1_DEBLOCKING_PARAMETERS *params_buf, TX_SIZE *tx_buf,
   263      int num_mis_in_lpf_unit_height_log2) {
   264    // TODO(aomedia:3276): Pass error_info to the low-level functions as required
   265    // in future to handle error propagation.
   266    (void)error_info;
   267    const int sb_cols =
   268        CEIL_POWER_OF_TWO(cm->mi_params.mi_cols, MAX_MIB_SIZE_LOG2);
   269    const int r = mi_row >> num_mis_in_lpf_unit_height_log2;
   270    int mi_col, c;
   271
   272    const bool joint_filter_chroma = (lpf_opt_level == 2) && plane > AOM_PLANE_Y;
   273    const int num_planes = joint_filter_chroma ? 2 : 1;
   274    assert(IMPLIES(joint_filter_chroma, plane == AOM_PLANE_U));
   275
   276    if (dir == 0) {
   277      for (mi_col = 0; mi_col < cm->mi_params.mi_cols; mi_col += MAX_MIB_SIZE) {
   278        c = mi_col >> MAX_MIB_SIZE_LOG2;
   279
   280        av1_setup_dst_planes(planes, cm->seq_params->sb_size, frame_buffer,
   281                             mi_row, mi_col, plane, plane + num_planes);
   282        if (lpf_opt_level) {
   283          if (plane == AOM_PLANE_Y) {
   284            av1_filter_block_plane_vert_opt(cm, xd, &planes[plane], mi_row,
   285                                            mi_col, params_buf, tx_buf,
   286                                            num_mis_in_lpf_unit_height_log2);
   287          } else {
   288            av1_filter_block_plane_vert_opt_chroma(
   289                cm, xd, &planes[plane], mi_row, mi_col, params_buf, tx_buf, plane,
   290                joint_filter_chroma, num_mis_in_lpf_unit_height_log2);
   291          }
   292        } else {
   293          av1_filter_block_plane_vert(cm, xd, plane, &planes[plane], mi_row,
   294                                      mi_col);
   295        }
   296        if (lf_sync != NULL) {
   297          sync_write(lf_sync, r, c, sb_cols, plane);
   298        }
   299      }
   300    } else if (dir == 1) {
   301      for (mi_col = 0; mi_col < cm->mi_params.mi_cols; mi_col += MAX_MIB_SIZE) {
   302        c = mi_col >> MAX_MIB_SIZE_LOG2;
   303
   304        if (lf_sync != NULL) {
   305          // Wait for vertical edge filtering of the top-right block to be
   306          // completed
   307          sync_read(lf_sync, r, c, plane);
   308
   309          // Wait for vertical edge filtering of the right block to be completed
   310          sync_read(lf_sync, r + 1, c, plane);
   311        }
   312
   313  #if CONFIG_MULTITHREAD
   314        if (lf_sync && lf_sync->num_workers > 1) {
   315          pthread_mutex_lock(lf_sync->job_mutex);
   316          const bool lf_mt_exit = lf_sync->lf_mt_exit;
   317          pthread_mutex_unlock(lf_sync->job_mutex);
   318          // Exit in case any worker has encountered an error.
   319          if (lf_mt_exit) return;
   320        }
   321  #endif
   322
   323        av1_setup_dst_planes(planes, cm->seq_params->sb_size, frame_buffer,
   324                             mi_row, mi_col, plane, plane + num_planes);
   325        if (lpf_opt_level) {
   326          if (plane == AOM_PLANE_Y) {
   327            av1_filter_block_plane_horz_opt(cm, xd, &planes[plane], mi_row,
   328                                            mi_col, params_buf, tx_buf,
   329                                            num_mis_in_lpf_unit_height_log2);
   330          } else {
   331            av1_filter_block_plane_horz_opt_chroma(
   332                cm, xd, &planes[plane], mi_row, mi_col, params_buf, tx_buf, plane,
   333                joint_filter_chroma, num_mis_in_lpf_unit_height_log2);
   334          }
   335        } else {
   336          av1_filter_block_plane_horz(cm, xd, plane, &planes[plane], mi_row,
   337                                      mi_col);
   338        }
   339      }
   340    }
  1300    (void)seq_params;
  1301  #endif  // !CONFIG_AV1_HIGHBITDEPTH
  1302  }
